import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"知识库导读","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787456457000}'),o={name:"guide/index.md"};function s(i,t,l,n,p,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="知识库导读" tabindex="-1">知识库导读 <a class="header-anchor" href="#知识库导读" aria-label="Permalink to &quot;知识库导读&quot;">​</a></h1><p>这是一份关于「用 AI 做创意广告」的实操笔记。它的目标不是解释 AI 的原理，而是回答一个具体问题：</p><blockquote><p>客户给了一句 brief，怎么在三天内交出一支能看的广告片 / 一组能上架的主图？</p></blockquote><h2 id="内容是怎么组织的" tabindex="-1">内容是怎么组织的 <a class="header-anchor" href="#内容是怎么组织的" aria-label="Permalink to &quot;内容是怎么组织的&quot;">​</a></h2><p>五个板块，对应做一支广告的五种需求：</p><table tabindex="0"><thead><tr><th>板块</th><th>回答什么问题</th><th>什么时候看</th></tr></thead><tbody><tr><td><a href="/method/">创意方法论</a></td><td>这活儿整体该怎么推？</td><td>接到 brief，还没动手时</td></tr><tr><td><a href="/prompts/">Prompt 模板库</a></td><td>这一句具体怎么写？</td><td>已经知道要什么，卡在措辞上</td></tr><tr><td><a href="/tools/">工具地图</a></td><td>用哪个工具？</td><td>选型阶段，或现有工具做不出效果时</td></tr><tr><td><a href="/pipelines/">实战流水线</a></td><td>这套工具串起来怎么跑？</td><td>要重复做同类项目，想把流程固化下来</td></tr><tr><td><a href="/cases/">案例拆解</a></td><td>别人是怎么做的？</td><td>没思路，想找参照</td></tr></tbody></table><p>方法论是<strong>骨</strong>，Prompt 是<strong>肉</strong>，工具是<strong>手</strong>，流水线是<strong>车间</strong>，案例是<strong>镜子</strong>。</p><p>另有 <a href="/templates/">写作模板</a>，是往库里加内容时用的，不算阅读板块。</p><h2 id="内容的可信度分级" tabindex="-1">内容的可信度分级 <a class="header-anchor" href="#内容的可信度分级" aria-label="Permalink to &quot;内容的可信度分级&quot;">​</a></h2><p>不是所有内容的确定性都一样。文中会用三种标记区分：</p><div class="tip custom-block"><p class="custom-block-title">稳定</p><p>经过验证、短期内不会变的判断。比如「镜头语言的词表」「创意流程的阶段划分」。</p></div><div class="warning custom-block"><p class="custom-block-title">易变</p><p>和具体工具、具体版本绑定的信息。比如「某模型的最大时长」。这类内容标注了「以官网为准」，看到时请自行核实。</p></div><div class="info custom-block"><p class="custom-block-title">待补充</p><p>留白，等实战经验填进来。点进去有写作模板，照着填即可。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想先建立整体认知 → <a href="/guide/landscape">AI 创意广告全景</a></li><li>想知道这个库怎么维护、怎么往里加东西 → <a href="/guide/how-to-use">怎么用这个知识库</a></li></ul>',15)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
